import { formatDue } from "./format-due"

const midnight = new Date("2026-09-30T00:00:00Z")
const afternoon = new Date("2026-09-30T14:00:00Z")

describe("formatDue", () => {
  it("says tomorrow for the next day", () => {
    expect(formatDue("2026-10-01", midnight)).toBe("tomorrow")
  })

  it("says today during the day", () => {
    expect(formatDue("2026-09-30", afternoon)).toBe("today")
  })

  it("says yesterday for the day before", () => {
    expect(formatDue("2026-09-29", midnight)).toBe("yesterday")
  })

  it("counts days ahead", () => {
    expect(formatDue("2026-10-03", midnight)).toBe("in 3 days")
  })
})

