/** A URL-safe name: lower case, words joined with hyphens. */
export function slug(value: string) {
  return value
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
}

import { expect, it } from "vitest"
import { slug } from "./slug"

it("joins words with hyphens", () => {
  expect(slug("Website Redesign")).toBe("website-redesign")
})

it("drops accents", () => {
  expect(slug("Café menu")).toBe("cafe-menu")
})

